from author_csharp_v2 import *

unit(95,
"کامپایلر C# کد را به IL همراه metadata در assembly تبدیل می‌کند. CLR محیط اجرای مدیریت‌شده،CTS قرارداد سیستم نوع و CLS زیرمجموعهٔ سازگار برای تعامل زبان‌هاست؛ BCL کتابخانه‌های پایه را می‌دهد. CLI در استاندارد Common Language Infrastructure با CLI به معنای ابزار خط فرمان دو کاربرد متفاوت مخفف‌اند. manifest هویت و وابستگی assembly را توصیف می‌کند. JIT متد را در زمان اجرا به کد ماشین تبدیل می‌کند و tiered compilation/PGO می‌توانند بعداً نسخهٔ بهینه‌تر بسازند. AOT بخش بیشتری را پیش از اجرا کامپایل می‌کند و محدودیت dynamic code دارد،اما همچنان می‌تواند GC داشته باشد. قرارداد زبان را از جزئیات بهینه‌سازی یک runtime جدا نگه دار.",
'Console.WriteLine(typeof(int).Assembly.GetName().Name);', 'System.Private.CoreLib',
("آیا Native AOT به معنای حذف GC است؟", "خیر؛ مدل کامپایل و مدیریت حافظه دو موضوع جدا هستند.", "بله؛ همهٔ objectها دستی آزاد می‌شوند.", "بله؛ reference typeها دیگر وجود ندارند.", "AOT زمان تولید کد ماشین را تغییر می‌دهد؛ مدیریت حافظهٔ مدیریت‌شده می‌تواند باقی بماند."),
domino("از کد تا اجرا", "مسیر معمول JIT را کامل کن؛ AOT یک مسیر دیگر است و نباید به جای IL معمول گذاشته شود.", ["source C#","compiler","IL و metadata در assembly","CLR و JIT","کد ماشین اجراشده","فایل متن روی UI"], [[0,1],[1,2],[2,3],[3,4],[0,5]], 4, [1,2,3], limit=5),
"یک کتابخانه و مصرف‌کننده بساز. نام assembly و نوع runtime را از reflection بخوان و با خروجی build مقایسه کن؛ مسیر JIT و AOT را با قرارداد GC جدا توضیح بده.",
'var assembly=typeof(Sample).Assembly;Console.WriteLine(assembly.GetName().Name is not null);\nConsole.WriteLine(assembly.GetType(typeof(Sample).FullName!)==typeof(Sample));\nclass Sample {}',
"هر دو نتیجه True باشند. نام واقعی assembly گزارش شود و از این مشاهده،زمان دقیق یا تعداد دفعات JIT استنتاج نشود.")

unit(96,
"stack frame برای فراخوانی و داده‌های محلی و managed heap برای objectهای مدیریت‌شده مفاهیم runtimeاند؛ valueها می‌توانند داخل object یا آرایه باشند و بهینه‌سازی می‌تواند محل را عوض کند. GC root و liveness تعیین می‌کنند چه داده‌ای هنوز قابل دسترسی است،نه صرفاً پایان متنی scope. object header،MethodTable و alignment جزئیات پیاده‌سازی‌اند و اندازه‌های آن‌ها به محیط وابسته است. boxing و closure می‌توانند تخصیص پنهان بسازند؛ کپی struct بزرگ هم هزینه دارد. virtual dispatch ممکن است با اطلاعات runtime devirtualize شود،اما قرارداد زبان همچنان همان رفتار قابل مشاهده است. اندازه و تخصیص را با ابزار بسنج،نه با شعار همهٔ valueها روی stack.",
'var holder=new Holder {Value=4};object boxed=holder.Value;\nConsole.WriteLine(boxed.GetType().IsValueType);\nclass Holder {public int Value;}', 'True',
("int field درون یک object چه چیزی را نقض می‌کند؟", "ادعای نادرست «تمام value typeها همیشه روی stack هستند»", "قرارداد کپی int", "وجود GC برای object", "نوع مقدار semantics کپی را بیان می‌کند؛ محل ذخیره به ظرف و runtime وابسته است."),
groups("کپی و تخصیص", "با فرض کد معمول و بدون حذف بهینه‌ساز،کارت‌ها را به عملیات دارای boxing و کپی سادهٔ int تقسیم کن.", ["boxing", "کپی int بدون boxing"], [["object x = 3","IComparable x = 3"],["int b = a","پارامتر int مقداری"]]),
"boxing عدد و capture متغیر را در نمونهٔ کوچک شناسایی کن. نسخهٔ بدون capture با static lambda بساز و رفتار را ثابت نگه دار؛ تخصیص را در Release اندازه بگیر.",
'int offset=2;Func<int,int> captured=n=>n+offset;\nFunc<int,int,int> explicitInput=static (n,delta)=>n+delta;\nif(captured(3)!=explicitInput(3,offset)) throw new Exception("behavior");\nobject boxed=3;Console.WriteLine((int)boxed);',
"3 چاپ شود و دو تابع نتیجهٔ 5 بدهند. گزارش allocation محیط و warm-up را ثبت کند؛ از روی یک cast،اندازهٔ object عمومی ادعا نشود.")

unit(97,
"GC دادهٔ قابل دسترسی از rootها را زنده نگه می‌دارد و دادهٔ غیرقابل دسترسی را طبق سیاست runtime جمع می‌کند. نسل‌ها،promotion و compaction هزینهٔ جمع‌آوری را توزیع می‌کنند؛ SOH،LOH و POH برای دسته‌های تخصیص و pinning نقش دارند. server/workstation و background GC تنظیمات رفتارند و تضمین توقف صفر نیستند. pinning جابه‌جایی داده را محدود می‌کند و می‌تواند بر fragmentation اثر بگذارد. WeakReference مالکیت قوی نمی‌دهد و هدف ممکن است پیش از مصرف از دست برود. leak مدیریت‌شده معمولاً دادهٔ هنوز rootشدهٔ غیرضروری است،مثلاً subscriber در event یا cache بی‌حد. GC.Collect درمان عمومی نشت نیست؛ ابتدا مسیر ارجاع و سیاست عمر را اصلاح کن.",
'var source=new Source();EventHandler handler=(_,_)=>{};source.Changed+=handler;\nConsole.WriteLine(source.Count);source.Changed-=handler;Console.WriteLine(source.Count);\nclass Source {public event EventHandler? Changed;public int Count=>Changed?.GetInvocationList().Length??0;}', '1\n0',
("اگر event در publisher زنده،subscriber را نگه دارد چه اصلاح ریشه‌ای لازم است؟", "مدیریت عمر اشتراک و unsubscribe مناسب", "فراخوانی مداوم GC.Collect", "تغییر تمام intها به long", "تا مرجع قویِ لازم‌نبوده باقی است،جمع‌آوری راه آزادکردن subscriber نیست."),
questions("ریشهٔ نگهداری", "در یک snapshot حافظه، یکی از سه مسیر نگهداری مرجع انتخاب شده است. با پرسش‌ها نوع پیوند و اثر قطع اشتراک را بررسی و مسیر پنهان را پیدا کن.", ["event در singleton زنده", "متغیر محلی تمام‌شده بدون root", "WeakReference تنها"], ["آیا مرجع قوی از شیء طولانی‌عمر دارد؟","آیا unsubscribe می‌تواند این مسیر را قطع کند؟"], [[True,True],[False,False],[False,False]], 0, limit=2),
"publisher طولانی‌عمر و subscriber دارای Dispose بساز. پس از Dispose تعداد handlerها صفر شود. با ابزار heap مسیر نگهداری نسخهٔ بدون unsubscribe را بررسی کن؛ به زمان جمع‌آوری قطعی تکیه نکن.",
'var source=new Source();using(var subscription=new Subscription(source)) Console.WriteLine(source.Count);\nConsole.WriteLine(source.Count);\nclass Source {public event EventHandler? Changed;public int Count=>Changed?.GetInvocationList().Length??0;}\nsealed class Subscription:IDisposable\n{readonly Source source;readonly EventHandler handler;bool closed;\npublic Subscription(Source source){this.source=source;handler=(_,_)=>{};source.Changed+=handler;}\npublic void Dispose(){if(closed)return;closed=true;source.Changed-=handler;}}',
"1 و 0 چاپ شود؛ Dispose تکراری بی‌اثر باشد. آزادشدن منطقی اشتراک از زمان واقعی GC جدا توضیح داده شود.")

unit(98,
"Dispose زمان آزادسازی منبع را با مالکیت روشن می‌کند؛ finalizer شبکهٔ نجات محدود برای منبع unmanaged است،نه مکان کار عادی یا دسترسی مطمئن به objectهای مدیریت‌شدهٔ دیگر. SafeHandle مدیریت handle بومی و آزادسازی قابل اطمینان‌تر را کپسوله می‌کند و اغلب نیاز به finalizer دستی wrapper را کم می‌کند. Dispose Pattern باید تکراری‌بودن،شکست ساخت و مالکیت جزءها را رعایت کند. SuppressFinalize فقط وقتی finalizer وجود دارد و cleanup انجام شده نقش دارد؛ آن را جادوی پاک‌کردن حافظه ندان. IAsyncDisposable برای cleanup async است. وابستگی قرضی را با منبع مالک‌شده مخلوط نکن؛ بستن زودهنگام منبع مشترک می‌تواند مصرف‌کنندهٔ دیگر را بشکند.",
'int released=0;var owner=new Owner(()=>released++);owner.Dispose();owner.Dispose();\nConsole.WriteLine(released);\nsealed class Owner(Action release):IDisposable {bool closed;public void Dispose(){if(closed)return;closed=true;release();}}', '1',
("کدام wrapper معمولاً نیاز به finalizer دستی را کمتر می‌کند؟", "SafeHandle با مالکیت درست handle بومی", "string نام فایل", "فقط فراخوانی GC.Collect در هر متد", "SafeHandle الگوی عمر handle را متمرکز می‌کند؛ wrapper فقط منابعی را که مالک است آزاد می‌کند."),
argument("منبع و حافظه", "فایل باز باید در پایان scope بسته شود حتی اگر حافظه هنوز زنده است.", ["Dispose تعیین‌شده لازم است", "فقط GC آینده کافی است", "handle فایل منبع سیستم‌عامل است", "نام متد کوتاه است", "زمان آزادسازی منبع با زمان جمع‌آوری حافظه یکی نیست", "همهٔ wrapperها finalizer می‌خواهند"], [[0,2,4]]),
"wrapper مالک IDisposable بساز که Dispose تکراری،منبع قرضی و خطای ساخت را درست رسیدگی کند. نیاز یا نبود نیاز finalizer را با وجود SafeHandle توضیح بده.",
'int calls=0;var resource=new Resource(()=>calls++);\nusing(var borrower=new Wrapper(resource,false)) {}Console.WriteLine(calls);\nvar owner=new Wrapper(resource,true);owner.Dispose();owner.Dispose();Console.WriteLine(calls);\nsealed class Resource(Action release):IDisposable {public void Dispose()=>release();}\nsealed class Wrapper(IDisposable resource,bool owns):IDisposable {bool closed;public void Dispose(){if(closed)return;closed=true;if(owns)resource.Dispose();}}',
"0 و 1 چاپ شود؛ borrower منبع را نبندد. wrapper صرفاً managed IDisposable finalizer بی‌دلیل نداشته باشد؛ شکست ساختِ پس از گرفتن منبع در تست جدا cleanup شود.")

unit(99,
"ref local و ref return به محل داده alias می‌دهند،نه کپی مستقل. ref readonly خواندن از محل را بدون نوشتن از همان مرجع محدود می‌کند؛ تغییر از alias دیگر ممکن است. ref conditional بین دو محل سازگار انتخاب می‌کند. scoped و escape analysis جلوگیری می‌کنند مرجع از عمر معتبر منبع بیرون برود. ref struct برای محدودیت‌های عمر طراحی شده و boxing معمول آن مجاز نیست؛ ref field در ref struct عمر مستقل از منبع ایجاد نمی‌کند. از C#13 ref struct می‌تواند interface پیاده کند و با allows ref struct در generic مناسب استفاده شود،اما محدودیت تبدیل به interface/boxing و ref safety باقی است. دادهٔ ref-like نباید از مرز await یا yield که عمرش را نامعتبر می‌کند عبور کند.",
'int[] values={1,2};ref int alias=ref values[0];alias=7;\nConsole.WriteLine(values[0]);', '7',
("آیا return ref به متغیر محلیِ متد معتبر است؟", "خیر؛ محل پس از خروج عمر معتبر ندارد.", "بله؛ ref عمر همهٔ stackها را بی‌نهایت می‌کند.", "فقط با ! همیشه امن می‌شود.", "ref safety از فرار مرجعِ محل کوتاه‌عمر جلوگیری می‌کند؛ باید محل با عمر معتبر برگردد."),
repair("مرجع فراری", "متد باید مرجع قابل استفاده پس از خروج بدهد؛ data آرایهٔ ورودی معتبر و local متغیر محلی است.", ["return ref local;", "return ref data[0];", "return ref new int();"], [0], ["عمر محل معتبر", "قابل تغییر از فراخواننده"], [([0],[False,False]),([1],[True,True]),([2],[False,False])]),
"متد ref return برای اولین عنصر آرایهٔ غیرخالی بنویس. تغییر از alias اصل را عوض کند. آرایهٔ خالی رد و نسخهٔ return ref local در تست کامپایل منفی ثبت شود.",
'int[] values={2,3};ref int first=ref First(values);first=9;Console.WriteLine(values[0]);\nstatic ref int First(int[] values) {if(values.Length==0) throw new ArgumentException("empty",nameof(values));return ref values[0];}',
"9 چاپ شود؛ محل آرایه عمر معتبر داشته باشد. خالی پیش از index رد و نمونهٔ فرار local توسط کامپایلر رد شود.")

unit(100,
"Span<T> و ReadOnlySpan<T> view پیوسته با محدودهٔ قابل بررسی‌اند؛ slicing معمولاً داده را کپی نمی‌کند. Memory<T> و ReadOnlyMemory<T> برای نگهداری و عبور از مرز async مناسب‌ترند،ولی مالکیت منبع را خودکار تضمین نمی‌کنند. ArraySegment هم view آرایه است. read-only view نوشتن از همان مسیر را منع می‌کند و immutability عمیق یا ثبات منبع از aliasهای دیگر را تضمین نمی‌کند. parser می‌تواند با ReadOnlySpan<char> بدون رشتهٔ میانی کار کند؛ نتیجهٔ نگهداری‌شده باید عمر مستقل لازم را داشته باشد. C#14 تبدیل‌های ضمنی Span و قواعد انتخاب overload را گسترش داده است؛ نوع مقصد و ref safety همچنان مهم‌اند. view buffer اجاره‌ای بعد از Return معتبر نیست.",
'int[] values={1,2,3};Span<int> middle=values.AsSpan(1,1);middle[0]=9;\nConsole.WriteLine(values[1]);', '9',
("ReadOnlySpan روی آرایه چه تضمینی ندارد؟", "تغییر نکردن آرایه از alias دیگری", "جلوگیری از نوشتن مستقیم از همان ReadOnlySpan", "نمایش محدودهٔ مشخص داده", "read-only بودن view با immutable بودن دادهٔ پشت آن متفاوت است."),
counter("view ثابت نیست", "ادعا: ReadOnlySpan همیشه snapshot مستقل و تغییرناپذیر منبع است.", ["آرایه از alias دیگر تغییر می‌کند", "ابتدا ToArray مستقل ساخته شده"], [("view مقدار جدید را می‌بیند","view مقدار قبلی را نگه می‌دارد",True,"view مشترک است؛ فقط دسترسی نوشتن از آن محدود شده."),("کپی مستقل مقدار قبلی را دارد","snapshot ثابت است",False,"این مسیر عمداً کپی ساخته است.")]),
"متن key=42 را با ReadOnlySpan برش و بدون ساخت substring عدد را parse کن. ورودی بدون = یا عدد خراب رد شود؛ خروجی ذخیره‌شده مقدار مستقل باشد.",
'Console.WriteLine(TryValue("key=42".AsSpan(),out int n)?n:-1);\nstatic bool TryValue(ReadOnlySpan<char> input,out int value)\n{value=0;int separator=input.IndexOf(\'=\');return separator>=0&&int.TryParse(input[(separator+1)..],out value);}',
"42 چاپ شود؛ ورودی بدون جداکننده و عدد خراب false بدهد. هیچ view به buffer منقضی‌شده نگهداری نشود و ادعای zero-allocation کل برنامه بدون اندازه‌گیری مطرح نشود.")

unit(101,
"ArrayPool اجارهٔ آرایه با حداقل طول خواسته‌شده می‌دهد؛ Length واقعی ممکن است بزرگ‌تر باشد و دادهٔ قبلی الزاماً پاک نیست. فقط محدودهٔ نوشته‌شده یا معتبر را مصرف کن. Return در finally برای موفقیت،خطا و لغو لازم است؛ پس از Return هیچ view یا alias مصرف نشود. دادهٔ حساس باید پیش از برگشت یا با clearArray پاک شود. MemoryPool و IMemoryOwner مالکیت memory را با Dispose بیان می‌کنند. stackalloc برای اندازهٔ کوچک محدود با عمر کوتاه مناسب است،نه اندازهٔ نامحدود از ورودی. inline array در C#12 ذخیرهٔ درون‌نوعی با قرارداد طول ثابت می‌دهد. pooling هزینهٔ هماهنگی و پیچیدگی عمر دارد و همیشه سریع‌تر نیست.",
'using System.Buffers;\nint[] buffer=ArrayPool<int>.Shared.Rent(2);\ntry {buffer[0]=3;buffer[1]=4;Console.WriteLine(buffer.AsSpan(0,2).ToArray().Sum());}\nfinally {ArrayPool<int>.Shared.Return(buffer,clearArray:true);}', '7',
("Rent(10) چه تضمینی دربارهٔ Length دارد؟", "حداقل 10؛ ممکن است بزرگ‌تر باشد.", "دقیقاً 10 در همهٔ poolها", "همیشه تمام عنصرها صفرند", "pool ظرفیت کافی می‌دهد؛ محدودهٔ منطقی و پاک‌بودن داده باید جدا مدیریت شوند."),
constraints("عمر buffer اجاره‌ای", "منبع باید در خطا هم برگردد و پس از برگشت مصرف نشود.", ["Rent", "نوشتن محدودهٔ معتبر", "مصرف view در عمر اجاره", "پاک‌کردن حساس و Return در finally", "پایان استفاده از تمام aliasها"], [[0,1],[1,2],[2,4],[4,3]]),
"buffer اجاره‌ای برای جمع داده بساز و Return را در finally بگذار. pool fake تعداد Rent/Return را در موفقیت،خطا و لغو بررسی کند؛ محدودهٔ اضافی خوانده نشود.",
'using System.Buffers;\nint count=3;byte[] buffer=ArrayPool<byte>.Shared.Rent(count);\ntry {buffer.AsSpan(0,count).Fill(2);int sum=0;foreach(byte value in buffer.AsSpan(0,count)) sum+=value;Console.WriteLine(sum);}\nfinally {ArrayPool<byte>.Shared.Return(buffer,clearArray:true);}',
"6 چاپ شود؛ فقط سه بایت منطقی مصرف شوند و برگشت دقیقاً یک بار باشد. اندازهٔ buffer از ورودی نامطمئن بدون سقف گرفته نشود.")

unit(102,
"TCP جریان byte بدون مرز پیام و UDP datagram با قرارداد دیگری است. partial read/write و framing باید در پروتکل رسیدگی شوند؛ یک Read الزاماً یک پیام نیست. BinaryPrimitives endian را صریح می‌کند تا فرمت به معماری دستگاه وابسته نشود. ReadOnlySequence ممکن است چند segment داشته باشد و SequenceReader خواندن مرحله‌ای را آسان می‌کند. IBufferWriter قرارداد درخواست و ثبت فضای نوشته‌شده است. PipeReader/Writer buffer و فشار برگشتی را مدیریت می‌کنند؛ AdvanceTo باید consumed و examined را درست اعلام کند،وگرنه داده گم یا مصرف متوقف می‌شود. zero-copy بودن همهٔ مسیر تضمین نیست؛ مالکیت و عمر هر buffer باید روشن باشد.",
'using System.Buffers.Binary;\nbyte[] bytes=new byte[4];BinaryPrimitives.WriteInt32BigEndian(bytes,258);\nConsole.WriteLine(BinaryPrimitives.ReadInt32BigEndian(bytes));', '258',
("چرا یک TCP Read مساوی یک پیام کامل نیست؟", "TCP جریان است و مرز پیام برنامه را حفظ نمی‌کند.", "چون تمام پیام‌ها فقط یک byte هستند.", "چون endian همیشه خودکار حل می‌شود.", "پروتکل باید طول یا delimiter و حد اندازه داشته باشد؛ تعداد واقعی خوانده‌شده مبناست."),
simulation("فریم دو تکه", "پیام طول 4 بایت در دو خواندن 2بایتی رسیده؛ فقط بعد از تکمیل پردازش کن.", ["دریافت دو بایت بعدی", "پردازش پیام"], ["0/4 بایت","2/4 بایت","4/4 بایت","پیام پردازش شد"], [[1,-1],[2,-1],[-1,3],[-1,-1]], [3], limit=3),
"فرمت طول 4بایتی big-endian و payload محدود بنویس. reader با ReadExactly طول و payload را بخواند؛ طول منفی،بیش از سقف و پایان زودرس رد شوند.",
'using System.Buffers.Binary;\nusing var stream=new MemoryStream(new byte[]{0,0,0,3,65,66,67});\nbyte[] header=new byte[4];stream.ReadExactly(header);int length=BinaryPrimitives.ReadInt32BigEndian(header);\nif(length<0||length>1024) throw new InvalidDataException("length");\nbyte[] payload=new byte[length];stream.ReadExactly(payload);Console.WriteLine(System.Text.Encoding.UTF8.GetString(payload));',
"ABC چاپ شود. تست stream کم‌خوان و EOF زودرس اضافه شود؛ طول ورودی پیش از تخصیص محدود و endian صریح باشد.")

unit(103,
"benchmark از فرضیه و baseline هم‌رفتار شروع می‌شود. Release،warm-up،نسخهٔ SDK/runtime،معماری،داده و تعداد تکرار باید ثبت شوند. Stopwatch برای آزمایش ساده مفید است،اما BenchmarkDotNet تکرار و تحلیل کنترل‌شده‌تری می‌دهد. زمان،throughput و allocation سه معیار متفاوت‌اند؛ کاهش یکی تضمین بهبود بقیه نیست. dotnet-counters نمای زنده،trace رویداد و sampling،gcdump گراف heap و dump وضعیت فرایند را برای تشخیص می‌دهند. JIT،GC و نویز ماشین نتایج کوچک را تغییر می‌دهند. نتیجهٔ اندازه‌گیری‌نشده نباید با درصد بهبود ساختگی گزارش شود. قبل از سریع‌کردن مسیر،درستی خروجی و گلوگاه واقعی را ثابت کن.",
'var watch=System.Diagnostics.Stopwatch.StartNew();\nint sum=Enumerable.Range(1,100).Sum();watch.Stop();\nConsole.WriteLine(sum);Console.WriteLine(watch.Elapsed>=TimeSpan.Zero);', '5050\nTrue',
("برای ادعای بهبود چه چیز لازم است؟", "رفتار برابر و اندازه‌گیری بازتولیدپذیر با محیط ثبت‌شده", "کوتاه‌تر شدن تعداد خطوط به‌تنهایی", "یک اجرای Debug بدون warm-up", "تفاوت زمان می‌تواند نویز یا تغییر رفتار باشد؛ baseline و روش اندازه‌گیری لازم‌اند."),
argument("شاهد کارایی", "دو پیاده‌سازی خروجی یکسان دارند. برای ادعای کاهش تخصیص،شاهد و دلیل مناسب انتخاب کن.", ["گزارش allocation تکرارپذیر لازم است", "نام Span کافی است", "بایت تخصیص‌یافته در Release برای هر دو اندازه‌گیری شده", "نسخهٔ دوم خطوط کمتری دارد", "معیار مستقیم با ورودی و محیط یکسان ادعا را پشتیبانی می‌کند", "همهٔ بهینه‌سازی‌ها همیشه سود دارند"], [[0,2,4]]),
"دو parser هم‌رفتار را در Release benchmark کن. نسخهٔ SDK،داده،warm-up،زمان و allocation را ثبت کن و اگر تفاوت در نویز بود همان را گزارش بده. نمونهٔ مرجع فقط برابری را اثبات می‌کند،نه سرعت را.",
'string input="42";int first=int.Parse(input);int second=int.Parse(input.AsSpan());\nif(first!=second) throw new Exception("baseline");Console.WriteLine(first);',
"42 چاپ و تست رفتار پاس شود. گزارش benchmark واقعی همراه روش و محدودیت ارائه شود؛ هیچ درصدی بدون اجرای اندازه‌گیری پذیرفته نیست.")

unit(104,
"کامپایلر async و iterator را به state machine تبدیل می‌کند تا متغیرهای زنده و محل ادامه حفظ شوند. IAsyncStateMachine و MoveNext بخشی از قرارداد پایین‌آوردن async هستند؛ awaiter pattern با GetAwaiter/IsCompleted/GetResult و continuation قرارداد انتظار را می‌دهد. TaskCompletionSource پایان کاری بیرونی را به task وصل می‌کند؛ RunContinuationsAsynchronously از اجرای ناخواستهٔ continuation در مسیر تکمیل جلوگیری می‌کند،اما تمام deadlockها را حل نمی‌کند. ValueTask و IValueTaskSource می‌توانند تخصیص بعضی مسیرها را کم کنند و قرارداد مصرف محدود دارند. هزینهٔ state machine،context و closure باید با مشاهدهٔ کد تولیدشده و benchmark سنجیده شود؛ هر await الزاماً یک تخصیص تازه نیست.",
'var completion=new TaskCompletionSource<int>(TaskCreationOptions.RunContinuationsAsynchronously);\ncompletion.SetResult(5);Console.WriteLine(await completion.Task);', '5',
("برای task تکمیل‌شونده از callback خارجی چه ابزار مستقیمی مناسب است؟", "TaskCompletionSource با سیاست continuation روشن", "حلقهٔ بی‌پایان روی bool بدون synchronization", "Thread.Sleep تا حدس پایان", "TCS پایان،خطا و لغو را با قرارداد task به مصرف‌کننده منتقل می‌کند."),
domino("از await تا نتیجه", "مسیر منطقی انتظار را کامل کن؛ continuation فقط پس از تکمیل کار ناتمام ادامه می‌یابد.", ["بررسی awaiter.IsCompleted", "ثبت continuation اگر ناتمام", "تکمیل کار", "ادامهٔ state machine", "GetResult و مشاهدهٔ خطا/نتیجه", "رهاکردن exception"], [[0,1],[1,2],[2,3],[3,4],[2,5]], 4, [1,2,3], limit=5),
"TCS را با موفقیت و exception از مسیر callback fake کامل کن. مصرف‌کننده هر دو را await کند؛ یک ValueTask را فقط یک بار مصرف و برای چند مصرفِ لازم به Task تبدیل کن.",
'var done=new TaskCompletionSource<int>(TaskCreationOptions.RunContinuationsAsynchronously);\nTask<int> task=done.Task;done.SetResult(7);Console.WriteLine(await task);\nValueTask<int> value=new(3);Task<int> reusable=value.AsTask();Console.WriteLine((await reusable)+(await reusable));',
"7 و 6 چاپ شود. هیچ ValueTask نامطمئن دوبار await نشود؛ TCS با TrySet در callbackهای ممکن‌التکرار سیاست روشن داشته باشد.")

unit(105,
"پروژهٔ کارایی از نسخهٔ درست شروع می‌شود و فقط گلوگاه مشاهده‌شده را تغییر می‌دهد. parser می‌تواند با Span رشتهٔ میانی را حذف کند،اما مدیریت عمر view و خطا نباید قربانی شود. pooling فقط با بازگشت قطعی buffer و سقف اندازه مجاز است. baseline و نسخهٔ تازه روی دادهٔ یکسان،خالی،خراب و مرزی باید خروجی و نوع شکست هم‌قرارداد داشته باشند. هزینهٔ پیچیدگی نگهداری را کنار زمان و allocation بنویس. گزارش قبل/بعد باید دستور بازتولید داشته باشد. اگر بهبود قابل تشخیص نیست،نسخهٔ خواناتر انتخاب معقولی است؛ تعداد قابلیت‌های پیشرفته هدف پروژه نیست.",
'string input="a=42";int split=int.Parse(input.Split(\'=\')[1]);int span=int.Parse(input.AsSpan(input.IndexOf(\'=\')+1));\nConsole.WriteLine(split==span);', 'True',
("پس از بهینه‌سازی parser چه چیز اول باید ثابت بماند؟", "خروجی و قرارداد خطا برای همهٔ ورودی‌های پشتیبانی‌شده", "فقط نام متد", "وجود حتمی ArrayPool حتی بدون سود", "سرعت با تغییر پنهان رفتار قابل مقایسه نیست؛ آزمون قرارداد پیش از benchmark لازم است."),
budget("بهینه‌سازی کافی", "طرح باید رفتار ثابت،شاهد واقعی و عمر buffer امن داشته باشد.", ["تست برابری خروجی و خطا", "benchmark بازتولیدپذیر", "مالکیت صریح view و buffer", "unsafe بدون اندازه‌گیری"], [1,1,1,5], [["رفتار"],["شاهد"],["عمر"],[]], ["رفتار","شاهد","عمر"], 3, [0,1,2]),
"parser key=int قبلی را با Span بازنویسی کن. تست خالی،نبود =،عدد خراب و مرز int را نگه دار. benchmark قبل/بعد و دلیل پذیرش یا رد پیچیدگی تازه را تحویل بده.",
'foreach(string input in new[]{"a=42","","a=bad","a=2147483647"})\n{bool ok=TryValue(input.AsSpan(),out int value);Console.WriteLine(ok?value.ToString():"invalid");}\nstatic bool TryValue(ReadOnlySpan<char> input,out int value)\n{value=0;int index=input.IndexOf(\'=\');return index>0&&int.TryParse(input[(index+1)..],out value);}',
"42،invalid،invalid،2147483647 چاپ شود. خروجی با baseline قرارداد یکسان داشته باشد؛ اندازه‌گیری واقعی و مالکیت مستقل نتیجه ثبت شود.")
